// Fixed public-only report transport. No imported report, configurable paths or
// binary copies; the report is generated by the fixed inspector in this process.
// Files are untrusted static observations, never receipts or producer authority.
import fs from 'node:fs';
import path from 'node:path';
import {createHash} from 'node:crypto';
import {gzipSync,gunzipSync} from 'node:zlib';
import {inspectFixedNativeStartupPublicBinaries} from './sealed-typescript-public-macho-inspection.mjs';
const RAW_LIMIT=24*1024*1024,PAYLOAD_LIMIT=2*1024*1024,DIRECTORY='.redue-public-inspection';
const FILES=['public-inspection.json.gz','manifest.json'];
const sha=v=>createHash('sha256').update(v).digest('hex');
const mark=s=>['dev','ino','mode','uid','gid','nlink','size','mtimeNs','ctimeNs'].map(k=>String(s[k])).join(':');
const directoryMark=s=>['dev','ino','mode','uid','gid'].map(k=>String(s[k])).join(':');
const guard=v=>{if(!v)throw Error('PUBLIC_REPORT_TRANSPORT_UNKNOWN');};
function lineage(file){const rows=[];for(let at=path.dirname(file);;at=path.dirname(at)){
 const s=fs.lstatSync(at,{bigint:true});guard(s.isDirectory()&&!s.isSymbolicLink()&&(s.uid===0n||s.uid===BigInt(process.getuid()))&&(s.mode&0o22n)===0n&&fs.realpathSync(at)===at);
 rows.push([at,directoryMark(s)]);if(at===path.dirname(at))return rows;
}}
function ownedDirectory(file){const s=fs.lstatSync(file,{bigint:true});guard(fs.realpathSync(file)===file&&s.isDirectory()&&!s.isSymbolicLink()&&s.uid===BigInt(process.getuid())&&(s.mode&0o7777n)===0o700n);return directoryMark(s);}
function put(file,body,rows,deadline){
 const parents=lineage(file),fd=fs.openSync(file,fs.constants.O_RDWR|fs.constants.O_CREAT|fs.constants.O_EXCL|fs.constants.O_NOFOLLOW|fs.constants.O_NONBLOCK,0o600);
 const row={file,fd,parents};rows.push(row);const first=fs.fstatSync(fd,{bigint:true});
 guard(first.isFile()&&first.uid===BigInt(process.getuid())&&first.nlink===1n&&(first.mode&0o7777n)===0o600n&&first.size===0n);
 let at=0;while(at<body.length){deadline();const n=fs.writeSync(fd,body,at,body.length-at,at);guard(Number.isInteger(n)&&n>0&&n<=body.length-at);at+=n;}fs.fsyncSync(fd);
 const before=fs.fstatSync(fd,{bigint:true});guard(before.isFile()&&before.uid===first.uid&&before.dev===first.dev&&before.ino===first.ino&&before.nlink===1n&&(before.mode&0o7777n)===0o600n&&before.size===BigInt(body.length));row.mark=mark(before);
 const bytes=Buffer.alloc(65536),hash=createHash('sha256');at=0;
 while(at<body.length){deadline();const requested=Math.min(bytes.length,body.length-at),n=fs.readSync(fd,bytes,0,requested,at);guard(Number.isInteger(n)&&n>0&&n<=requested);hash.update(bytes.subarray(0,n));at+=n;}
 guard(hash.digest('hex')===sha(body)&&mark(fs.fstatSync(fd,{bigint:true}))===row.mark);named(row);return row;
}
function named(r){guard(fs.realpathSync(r.file)===r.file&&mark(fs.lstatSync(r.file,{bigint:true}))===r.mark&&JSON.stringify(lineage(r.file))===JSON.stringify(r.parents));guard(mark(fs.lstatSync(r.file,{bigint:true}))===r.mark);}
export function collectFixedPublicMachOInspectionFiles(){
 const summary={schema:1,scope:'FIXED_PUBLIC_INSPECTION_FILE_TRANSPORT_ONLY',transport:'UNKNOWN',inspectionOutcome:'UNKNOWN',reason:'PRECONDITION_UNAVAILABLE',
  directory:DIRECTORY,files:[],rawBytes:null,compressedBytes:null,payloadBytes:null,rawSha256:null,compressedSha256:null,manifestSha256:null,
  ownedDescriptorsClosed:false,untrustedPublicData:true,profileApproved:false,sealed:false,reuseEligible:false,nativeAgentLaunches:0,models:0,targetExecutions:0,compilerCheckExecutions:0};
 let reason='PRECONDITION_UNAVAILABLE',directory=null,identity=null,parents=null;const rows=[],start=process.hrtime.bigint();
 const deadline=()=>guard(process.hrtime.bigint()-start<120000000000n);
 const current=()=>{deadline();guard(ownedDirectory(directory)===identity&&JSON.stringify(lineage(directory))===JSON.stringify(parents));for(const row of rows)named(row);deadline();};
 try{
  guard(arguments.length===0&&process.platform==='darwin'&&process.arch==='arm64'&&process.version==='v22.13.0'&&process.getuid()>0&&process.getuid()===process.geteuid()&&process.getgid()===process.getegid()&&fs.constants.O_NOFOLLOW!==undefined&&fs.constants.O_NONBLOCK!==undefined);
  const cwd=process.cwd(),root=fs.lstatSync(cwd,{bigint:true});guard(path.isAbsolute(cwd)&&fs.realpathSync(cwd)===cwd&&root.isDirectory()&&!root.isSymbolicLink()&&root.uid===BigInt(process.getuid())&&(root.mode&0o22n)===0n);lineage(cwd);
  directory=path.join(cwd,DIRECTORY);reason='OUTPUT_DIRECTORY_UNAVAILABLE';fs.mkdirSync(directory,{mode:0o700});identity=ownedDirectory(directory);parents=lineage(directory);guard(fs.readdirSync(directory).length===0);current();
  reason='PUBLIC_INSPECTION_UNAVAILABLE';const inspection=inspectFixedNativeStartupPublicBinaries();current();
  guard(inspection?.schema===1&&inspection.interpretation==='redue-fixed-public-macho-inspection@2'&&inspection.scope==='PUBLIC_STATIC_SOURCE_INSPECTION_ONLY'&&inspection.publicOutputUntrusted===true&&inspection.profileApproved===false&&inspection.sealed===false&&inspection.reuseEligible===false&&inspection.models===0&&inspection.nativeAgentLaunches===0&&inspection.targetExecutions===0&&inspection.compilerCheckExecutions===0&&['UNKNOWN','PUBLIC_OUTPUT_COLLECTED_NOT_BEHAVIOR_PROOF'].includes(inspection.outcome));
  summary.inspectionOutcome=inspection.outcome;reason='PUBLIC_PAYLOAD_LIMIT_OR_ENCODING';
  const raw=Buffer.from(JSON.stringify(inspection)+'\n','utf8');guard(raw.length<=RAW_LIMIT);deadline();
  const compressed=gzipSync(raw,{level:9,mtime:0,maxOutputLength:PAYLOAD_LIMIT});guard(Buffer.isBuffer(compressed)&&compressed.length<=PAYLOAD_LIMIT);deadline();
  guard(gunzipSync(compressed,{maxOutputLength:RAW_LIMIT}).equals(raw));deadline();
  const manifest=Buffer.from(JSON.stringify({schema:1,scope:'UNTRUSTED_PUBLIC_MACHO_INSPECTION_DATA_ONLY',interpretation:inspection.interpretation,outcome:inspection.outcome,
   rawFile:'public-inspection.json',compressedFile:FILES[0],rawBytes:raw.length,compressedBytes:compressed.length,rawSha256:sha(raw),compressedSha256:sha(compressed),
   rawDecompressionLimit:RAW_LIMIT,payloadLimit:PAYLOAD_LIMIT,profileApproved:false,sealed:false,reuseEligible:false,nativeAgentLaunches:0,models:0,targetExecutions:0,compilerCheckExecutions:0})+'\n');
  guard(manifest.length<=4096&&compressed.length+manifest.length<=PAYLOAD_LIMIT);current();reason='PUBLIC_FILE_PERSISTENCE_UNAVAILABLE';
  put(path.join(directory,FILES[0]),compressed,rows,deadline);current();put(path.join(directory,FILES[1]),manifest,rows,deadline);current();
  Object.assign(summary,{transport:'PUBLIC_REPORT_FILES_READY',reason:'PUBLIC_DATA_PERSISTED_NOT_TRUSTED',files:[...FILES],rawBytes:raw.length,compressedBytes:compressed.length,payloadBytes:compressed.length+manifest.length,rawSha256:sha(raw),compressedSha256:sha(compressed),manifestSha256:sha(manifest)});reason=summary.reason;
 }catch{/* Keep partial fresh files as UNKNOWN; never print errors or public output. */}
 finally{
  let closed=true;for(const row of rows)try{fs.closeSync(row.fd);}catch{closed=false;}summary.ownedDescriptorsClosed=closed;
  try{if(summary.transport==='PUBLIC_REPORT_FILES_READY'){guard(closed);current();}}catch{summary.transport='UNKNOWN';reason='CLOSING_FILE_IDENTITY_UNAVAILABLE';}
  if(!closed){summary.transport='UNKNOWN';reason='DESCRIPTOR_CLOSE_UNOBSERVED';}
 }
 summary.reason=reason;Object.freeze(summary.files);return Object.freeze(summary);
}
